import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Calendar, Users, User, Home, Sparkles, LayoutDashboard, Package, CreditCard, UserCheck, Sun, Moon, Trophy } from 'lucide-react';
import { AIChat } from './AIChat';
import { useUser } from '../context/UserContext';
import { useTheme } from '../ThemeContext';

interface LayoutProps {
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { role } = useUser();
  const { theme, toggleTheme } = useTheme();
  const [isChatOpen, setIsChatOpen] = useState(false);

  const isActive = (path: string, search?: string) => {
    if (search) {
      return location.pathname === path && location.search.includes(search);
    }
    return location.pathname === path;
  };

  const NavItem = ({ path, search, icon: Icon, label }: { path: string, search?: string, icon: any, label: string }) => {
    const active = isActive(path, search);
    return (
      <button
        onClick={() => navigate(search ? `${path}${search}` : path)}
        className={`flex flex-col items-center justify-center w-full h-full py-2 transition-colors duration-300 group ${
          active 
            ? 'text-brand-secondary' 
            : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
        }`}
      >
        <Icon size={24} strokeWidth={active ? 2.5 : 2} className={`mb-1 transition-transform group-active:scale-95 ${active ? 'scale-110' : ''}`} />
        <span className="text-[10px] font-medium">{label}</span>
      </button>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 dark:bg-brand-dark overflow-hidden transition-colors duration-500 font-sans relative">
      {/* Global Header/Actions Overlay */}
      <div className="fixed top-6 right-6 z-[100] flex items-center space-x-3">
        <button 
          onClick={toggleTheme}
          title={theme === 'dark' ? "Switch to Light Mode" : "Switch to Dark Mode"}
          className="w-12 h-12 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border border-slate-200 dark:border-slate-800 rounded-2xl flex items-center justify-center text-slate-900 dark:text-white shadow-2xl active:scale-90 hover:scale-105 transition-all group"
        >
          {theme === 'dark' ? (
            <Sun size={20} className="group-hover:rotate-45 transition-transform" />
          ) : (
            <Moon size={20} className="group-hover:-rotate-12 transition-transform" />
          )}
        </button>
      </div>

      <main className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
        {children}
      </main>

      {/* AI Assistant FAB - Only for Players */}
      {role === 'PLAYER' && !isChatOpen && (
        <button
          onClick={() => setIsChatOpen(true)}
          className="fixed bottom-24 right-6 z-40 w-14 h-14 bg-brand-secondary text-white dark:text-black rounded-2xl shadow-2xl flex items-center justify-center hover:scale-105 active:scale-95 transition-transform group"
        >
          <Sparkles size={24} className="group-hover:rotate-12 transition-transform" />
        </button>
      )}

      {/* AI Chat Overlay */}
      {isChatOpen && <AIChat onClose={() => setIsChatOpen(false)} />}

      <div className="fixed bottom-0 left-0 right-0 h-20 bg-white/90 dark:bg-black/90 backdrop-blur-md border-t border-slate-200 dark:border-slate-800 flex justify-around items-center z-50 px-2 pb-2 safe-area-bottom">
          {role === 'PLAYER' ? (
            <>
              <NavItem path="/home" icon={Home} label="Home" />
              <NavItem path="/match-center" icon={Trophy} label="Play" />
              <NavItem path="/bookings" icon={Calendar} label="Bookings" />
              <NavItem path="/teams" icon={Users} label="Teams" />
              <NavItem path="/profile" icon={User} label="Profile" />
            </>
          ) : (
            <>
              <NavItem path="/owner" search="tab=Dashboard" icon={LayoutDashboard} label="Dashboard" />
              <NavItem path="/owner" search="tab=Facilities" icon={Package} label="Facilities" />
              <NavItem path="/owner" search="tab=Bookings" icon={Calendar} label="Bookings" />
              <NavItem path="/owner" search="tab=Staff" icon={UserCheck} label="Staff" />
              <NavItem path="/owner" search="tab=Finance" icon={CreditCard} label="Finance" />
            </>
          )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { 
    Plus, Users, X, ChevronRight, Share2, 
    Calendar, Phone, Shield, Trash2, 
    CheckCircle, AlertCircle, Clock, MapPin,
    DollarSign, MessageCircle, Copy, ExternalLink, Search
} from 'lucide-react';
import { useBooking } from '../context/BookingContext';

interface Member {
    id: string;
    name: string;
    contact: string;
    isCaptain: boolean;
    hasPaid: boolean;
}

interface Team {
    id: string;
    name: string;
    members: Member[];
}

export const Teams: React.FC = () => {
  const navigate = useNavigate();
  const { bookings } = useBooking();

  const [teams, setTeams] = useState<Team[]>([
    {
      id: 't1',
      name: 'Kampala Kings',
      members: [
        { id: 'm1', name: 'David Okello', contact: '0772000000', isCaptain: true, hasPaid: true },
        { id: 'm2', name: 'Mike Smith', contact: '0788112233', isCaptain: false, hasPaid: false },
        { id: 'm3', name: 'Sarah Kibone', contact: '0701112233', isCaptain: false, hasPaid: true },
      ]
    }
  ]);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);
  const [newTeamName, setNewTeamName] = useState('');

  const handleCreateTeam = () => {
    if (!newTeamName.trim()) return;
    const newTeam: Team = {
      id: Math.random().toString(36).substr(2, 9),
      name: newTeamName,
      members: [{ id: 'me', name: 'You (Captain)', contact: '0770000000', isCaptain: true, hasPaid: true }]
    };
    setTeams([...teams, newTeam]);
    setNewTeamName('');
    setShowCreateModal(false);
  };

  const togglePayment = (teamId: string, memberId: string) => {
    setTeams(prev => prev.map(t => {
      if (t.id !== teamId) return t;
      return {
        ...t,
        members: t.members.map(m => m.id === memberId ? { ...m, hasPaid: !m.hasPaid } : m)
      };
    }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('Contact copied for MoMo payment!');
  };

  const shareToWhatsApp = (team: Team, booking?: any) => {
    const text = booking 
      ? `⚽ SQUAD CALL: Match at ${booking.turfName} on ${booking.date} @ ${booking.time}. Captain: ${team.members.find(m => m.isCaptain)?.name}. Please clear your fees via Footlink!`
      : `Hey! I've added you to the ${team.name} squad on Footlink. Check our next booking here.`;

    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const getTeamBooking = (teamName: string) => {
    return bookings.find(b => b.userName.includes(teamName) || (teamName === 'Kampala Kings' && b.id === 'b1'));
  };

  return (
    <Layout>
      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
          <div className="bg-white dark:bg-brand-surface w-full max-w-sm rounded-[2.5rem] p-8 animate-slideUp">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black uppercase italic">New Squad</h2>
              <button onClick={() => setShowCreateModal(false)}><X className="text-slate-400" /></button>
            </div>
            <input 
              type="text" 
              autoFocus
              placeholder="e.g. Ntinda Legends"
              value={newTeamName}
              onChange={(e) => setNewTeamName(e.target.value)}
              className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl p-4 text-lg font-bold mb-6 outline-none focus:ring-2 focus:ring-brand-secondary"
            />
            <button 
              onClick={handleCreateTeam}
              className="w-full bg-brand-secondary text-white dark:text-black py-4 rounded-xl font-black uppercase tracking-widest"
            >
              Create Team
            </button>
          </div>
        </div>
      )}

      <div className="p-5 pt-8 bg-slate-50 dark:bg-brand-dark min-h-screen pb-32">
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">Teams</h1>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-2">Logistics & Roster</p>
          </div>
          <button 
            onClick={() => setShowCreateModal(true)}
            className="bg-brand-secondary text-white dark:text-black p-3 rounded-2xl shadow-xl active:scale-95 transition-transform"
          >
            <Plus size={24} />
          </button>
        </div>

        {/* Squad Finder Link */}
        <button 
          onClick={() => navigate('/squad-finder')}
          className="w-full bg-white dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm mb-8 flex items-center justify-between group active:scale-[0.98] transition-all"
        >
           <div className="flex items-center">
              <div className="w-10 h-10 bg-blue-500/10 text-blue-500 rounded-xl flex items-center justify-center mr-3">
                 <Search size={20} />
              </div>
              <div className="text-left">
                 <h3 className="font-bold text-slate-900 dark:text-white text-sm">Recruit & Find</h3>
                 <p className="text-slate-500 text-xs">Find players or join a new team</p>
              </div>
           </div>
           <ChevronRight size={20} className="text-slate-400 group-hover:text-brand-secondary transition-colors" />
        </button>

        <div className="space-y-6">
          {teams.map(team => {
            const activeBooking = getTeamBooking(team.name);
            const isDetailed = selectedTeamId === team.id;
            const paidCount = team.members.filter(m => m.hasPaid).length;
            const collectionProgress = (paidCount / team.members.length) * 100;

            return (
              <div key={team.id} className="bg-white dark:bg-brand-surface border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-sm transition-all border-b-4 border-b-slate-200 dark:border-b-slate-800">
                <div className="p-6">
                  <div className="flex justify-between items-start mb-6">
                    <div onClick={() => setSelectedTeamId(isDetailed ? null : team.id)} className="cursor-pointer">
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">{team.name}</h2>
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest flex items-center mt-1">
                        <Users size={12} className="mr-1 text-brand-secondary" /> {team.members.length} Players
                      </p>
                    </div>
                    <button 
                      onClick={() => shareToWhatsApp(team, activeBooking)}
                      className="p-3 bg-emerald-500/10 text-emerald-600 rounded-2xl border border-emerald-500/20 active:scale-95 transition-all"
                    >
                      <MessageCircle size={20} />
                    </button>
                  </div>

                  {/* Collection Progress */}
                  <div className="mb-6">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Collection Progress</span>
                        <span className="text-[10px] font-black text-brand-secondary uppercase">{paidCount}/{team.members.length} Paid</span>
                    </div>
                    <div className="w-full h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-brand-secondary transition-all duration-700" 
                          style={{ width: `${collectionProgress}%` }}
                        />
                    </div>
                  </div>

                  <div className="mt-4 flex justify-end items-center">
                    <button 
                        onClick={() => setSelectedTeamId(isDetailed ? null : team.id)}
                        className="text-brand-secondary text-xs font-black uppercase tracking-widest"
                    >
                      {isDetailed ? 'Hide Roster' : 'Manage Roster'}
                    </button>
                  </div>
                </div>

                {isDetailed && (
                  <div className="px-6 pb-6 pt-2 border-t border-slate-50 dark:border-slate-800 animate-fadeIn">
                    <div className="space-y-3 mt-4">
                      {team.members.map(member => (
                        <div key={member.id} className="flex flex-col p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                          <div className="flex items-center justify-between">
                            <div className="flex items-center">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center mr-3 ${member.isCaptain ? 'bg-slate-900 text-white dark:bg-white dark:text-black' : 'bg-slate-200 dark:bg-slate-700 text-slate-500'}`}>
                                <Shield size={14} />
                              </div>
                              <div>
                                <p className="text-sm font-bold text-slate-900 dark:text-white">
                                  {member.name} {member.isCaptain && <span className="text-[10px] text-brand-secondary ml-1">(C)</span>}
                                </p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase">{member.contact}</p>
                              </div>
                            </div>

                            <div className="flex items-center space-x-2">
                                <button 
                                  onClick={() => togglePayment(team.id, member.id)}
                                  className={`p-2 rounded-xl transition-all ${member.hasPaid ? 'bg-emerald-500 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-400'}`}
                                >
                                    <CheckCircle size={16} />
                                </button>
                                <button 
                                  onClick={() => copyToClipboard(member.contact)}
                                  className="p-2 bg-slate-200 dark:bg-slate-700 text-slate-500 rounded-xl"
                                >
                                  <Copy size={16} />
                                </button>
                                <a 
                                  href={`tel:*165#`}
                                  className="p-2 bg-amber-500/10 text-amber-600 rounded-xl border border-amber-500/20"
                                >
                                  <ExternalLink size={16} />
                                </a>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>

                    <div className="mt-6 flex items-start bg-amber-500/5 p-4 rounded-2xl border border-amber-500/10">
                        <AlertCircle size={16} className="text-amber-500 mr-3 flex-shrink-0" />
                        <p className="text-slate-500 dark:text-slate-400 text-[10px] leading-relaxed font-medium">
                            Use the <ExternalLink className="inline" size={10} /> icon to trigger MoMo USSD (*165#) or <Copy className="inline" size={10} /> to copy their number for payment.
                        </p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </Layout>
  );
};

