import React, { createContext, useContext, useState } from 'react';
import { USER_STATS, BADGES } from '../constants';

export interface Badge {
  id: string;
  name: string;
  icon: string;
  desc: string;
  earned: boolean;
}

interface UserStats {
  level: number;
  currentXP: number;
  nextLevelXP: number;
  rank: number;
  totalGames: number;
}

export interface UserProfileData {
  name: string;
  email: string;
  phone: string;
  avatar: string;
  bio: string;
}

export type UserRole = 'PLAYER' | 'OWNER';

interface UserContextType {
  role: UserRole;
  setRole: (role: UserRole) => void;
  stats: UserStats;
  badges: Badge[];
  addXP: (amount: number) => void;
  followedTournaments: string[];
  toggleFollowTournament: (tournamentName: string) => void;
  userProfile: UserProfileData;
  updateProfile: (data: Partial<UserProfileData>) => void;
}

const UserContext = createContext<UserContextType | undefined>(undefined);

const INITIAL_PROFILE: UserProfileData = {
    name: 'David Okello',
    email: 'david.okello@example.com',
    phone: '0772123456',
    avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=256&h=256&fit=crop',
    bio: 'Sunday League Legend ⚽ | Midfield Maestro'
};

export const UserProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [role, setRole] = useState<UserRole>('PLAYER');
  const [stats, setStats] = useState<UserStats>(USER_STATS);
  const [badges, setBadges] = useState<Badge[]>(BADGES);
  const [followedTournaments, setFollowedTournaments] = useState<string[]>(['Uganda Premier League']);
  const [userProfile, setUserProfile] = useState<UserProfileData>(INITIAL_PROFILE);

  const addXP = (amount: number) => {
    setStats(prev => {
      let newXP = prev.currentXP + amount;
      let newLevel = prev.level;
      let newNextLevelXP = prev.nextLevelXP;

      while (newXP >= newNextLevelXP) {
        newXP -= newNextLevelXP;
        newLevel += 1;
        newNextLevelXP = Math.floor(newNextLevelXP * 1.2);
      }

      return {
        ...prev,
        currentXP: newXP,
        level: newLevel,
        nextLevelXP: newNextLevelXP,
        totalGames: prev.totalGames + (amount > 0 ? 1 : 0)
      };
    });
  };

  const toggleFollowTournament = (name: string) => {
    setFollowedTournaments(prev => 
      prev.includes(name) ? prev.filter(t => t !== name) : [...prev, name]
    );
  };

  const updateProfile = (data: Partial<UserProfileData>) => {
      setUserProfile(prev => ({ ...prev, ...data }));
  };

  return (
    <UserContext.Provider value={{ role, setRole, stats, badges, addXP, followedTournaments, toggleFollowTournament, userProfile, updateProfile }}>
      {children}
    </UserContext.Provider>
  );
};

export const useUser = () => {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('useUser must be used within a UserProvider');
  }
  return context;
};

