import React, { useState, useMemo } from 'react';
import { Layout } from '../components/Layout';
import { useBooking } from '../context/BookingContext';
import { 
    Calendar, Clock, MapPin, QrCode, History, 
    ChevronRight, Share2, Info, Search, X, 
    AlertCircle, Navigation, CalendarPlus, Trash2, 
    CheckCircle, ArrowLeft, MoreHorizontal, Download
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Booking } from '../types';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

export const Bookings: React.FC = () => {
  const { bookings, updateBookingStatus, turfs } = useBooking();
  const navigate = useNavigate();

  // UI States
  const [filter, setFilter] = useState<'Upcoming' | 'Past' | 'Cancelled'>('Upcoming');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
  const [showCancelConfirm, setShowCancelConfirm] = useState<string | null>(null);
  const [isDownloading, setIsDownloading] = useState(false);

  // Filter Logic
  const filteredBookings = useMemo(() => {
    return bookings.filter(b => {
      const matchSearch = b.turfName.toLowerCase().includes(searchTerm.toLowerCase());
      const isPast = new Date(b.date) < new Date(new Date().setHours(0,0,0,0));
      const isCancelled = b.status === 'CANCELLED';

      let matchesFilter = false;
      if (filter === 'Cancelled') matchesFilter = isCancelled;
      else if (filter === 'Past') matchesFilter = isPast && !isCancelled;
      else matchesFilter = !isPast && !isCancelled;

      return matchSearch && matchesFilter;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [bookings, filter, searchTerm]);

  const handleCancelBooking = (id: string) => {
    updateBookingStatus(id, 'CANCELLED');
    setShowCancelConfirm(null);
    if (selectedBooking?.id === id) setSelectedBooking(null);
  };

  const openDirections = (location: string) => {
    window.open(`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(location)}`, '_blank');
  };

  const handleShare = async (booking: Booking) => {
    const shareData = {
        title: `Match at ${booking.turfName}`,
        text: `I've booked a slot at ${booking.turfName} for ${booking.date} at ${booking.time}. See you there!`,
        url: window.location.origin
    };
    try {
        if (navigator.share) await navigator.share(shareData);
        else alert("Invite link copied!");
    } catch (e) { console.error(e); }
  };

  const handleDownloadTicket = async () => {
      const input = document.getElementById('ticket-node');
      if (!input) return;

      setIsDownloading(true);
      try {
        const canvas = await html2canvas(input, { scale: 2, useCORS: true });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a6'); // A6 size for ticket
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();

        pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
        pdf.save('footlink-ticket.pdf');
      } catch (err) {
        console.error(err);
        alert("Failed to download ticket.");
      } finally {
        setIsDownloading(false);
      }
  };

  // --- SUB-COMPONENTS ---

  const TicketModal = ({ booking }: { booking: Booking }) => {
    const turf = turfs.find(t => t.id === booking.turfId);
    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fadeIn">
            <div className="w-full max-w-sm animate-slideUp">
                <div className="flex justify-end mb-4">
                    <button onClick={() => setSelectedBooking(null)} className="p-2 bg-white/10 rounded-full text-white">
                        <X size={24} />
                    </button>
                </div>

                <div id="ticket-node" className="bg-white text-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl relative">
                    {/* Top Notch */}
                    <div className="p-8 border-b border-dashed border-slate-200 relative">
                        <div className="absolute bottom-0 left-0 transform -translate-x-1/2 translate-y-1/2 w-8 h-8 bg-black rounded-full"></div>
                        <div className="absolute bottom-0 right-0 transform translate-x-1/2 translate-y-1/2 w-8 h-8 bg-black rounded-full"></div>

                        <div className="text-center mb-8">
                            <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-1">Official Digital Pass</p>
                            <h2 className="text-2xl font-black italic tracking-tighter uppercase">{booking.turfName}</h2>
                            <p className="text-slate-400 text-[10px] flex items-center justify-center font-bold mt-1">
                                <MapPin size={10} className="mr-1" /> {turf?.location || 'Kampala, Uganda'}
                            </p>
                        </div>

                        <div className="grid grid-cols-2 gap-y-6 text-left">
                            <div>
                                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Match Day</p>
                                <p className="font-black text-sm">{booking.date}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Kick Off</p>
                                <p className="font-black text-sm">{booking.time} ({booking.duration}h)</p>
                            </div>
                            <div>
                                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Pass ID</p>
                                <p className="font-black text-sm font-mono">#{booking.id}</p>
                            </div>
                            <div className="text-right">
                                <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Fee Settled</p>
                                <p className="font-black text-emerald-600 text-sm">UGX {booking.price.toLocaleString()}</p>
                            </div>
                        </div>
                    </div>

                    <div className="p-8 flex flex-col items-center justify-center bg-slate-50/50">
                        <div className="bg-white p-4 rounded-3xl shadow-inner border border-slate-100 mb-4 group">
                            <QrCode size={160} className="text-slate-900" />
                        </div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Scan for entry</p>
                    </div>
                </div>

                <div className="mt-6 grid grid-cols-3 gap-3">
                    <button 
                        onClick={() => openDirections(turf?.location || booking.turfName)}
                        className="bg-white/10 border border-white/20 text-white py-4 rounded-2xl font-bold text-sm flex items-center justify-center active:scale-95 transition-all"
                    >
                        <Navigation size={18} />
                    </button>
                    <button 
                        onClick={() => handleShare(booking)}
                        className="bg-white/10 border border-white/20 text-white py-4 rounded-2xl font-bold text-sm flex items-center justify-center active:scale-95 transition-all"
                    >
                        <Share2 size={18} />
                    </button>
                    <button 
                        onClick={handleDownloadTicket}
                        disabled={isDownloading}
                        className="bg-brand-secondary text-white py-4 rounded-2xl font-bold text-sm flex items-center justify-center active:scale-95 transition-all"
                    >
                        <Download size={18} />
                    </button>
                </div>
            </div>
        </div>
    );
  };

  return (
    <Layout>
        {/* Modals */}
        {selectedBooking && <TicketModal booking={selectedBooking} />}

        {showCancelConfirm && (
            <div className="fixed inset-0 z-[70] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-fadeIn">
                <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] max-w-xs w-full text-center border border-slate-200 dark:border-slate-800">
                    <div className="w-16 h-16 bg-red-100 dark:bg-red-500/10 text-red-500 rounded-full flex items-center justify-center mx-auto mb-4">
                        <AlertCircle size={32} />
                    </div>
                    <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Cancel Match?</h3>
                    <p className="text-slate-500 text-sm mb-8">This action cannot be undone. Refunds are subject to venue policy.</p>
                    <div className="space-y-3">
                        <button 
                            onClick={() => handleCancelBooking(showCancelConfirm)}
                            className="w-full py-4 bg-red-500 text-white rounded-xl font-bold shadow-lg shadow-red-500/20"
                        >
                            Yes, Cancel Booking
                        </button>
                        <button 
                            onClick={() => setShowCancelConfirm(null)}
                            className="w-full py-4 text-slate-500 font-bold"
                        >
                            Go Back
                        </button>
                    </div>
                </div>
            </div>
        )}

        <div className="p-5 pt-8 bg-slate-50 dark:bg-brand-dark min-h-screen pb-32">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight italic uppercase">Bookings</h1>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-1">Match Management</p>
                </div>
                <div className="w-12 h-12 rounded-2xl bg-brand-secondary/10 flex items-center justify-center text-brand-secondary border border-brand-secondary/20">
                    <Calendar size={24} />
                </div>
            </div>

            {/* Functional Search & Filter Bar */}
            <div className="space-y-4 mb-8">
                <div className="relative group">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-brand-secondary transition-colors" size={20} />
                    <input 
                        type="text" 
                        placeholder="Search venues or matches..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-4 pl-12 pr-4 text-sm focus:ring-2 focus:ring-brand-secondary outline-none transition-all shadow-sm"
                    />
                </div>

                <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-x-auto scrollbar-hide">
                    {(['Upcoming', 'Past', 'Cancelled'] as const).map(f => (
                        <button 
                            key={f}
                            onClick={() => setFilter(f)}
                            className={`flex-1 min-w-[100px] py-3 rounded-xl font-bold text-xs transition-all ${
                                filter === f 
                                ? 'bg-brand-secondary text-white dark:text-black shadow-lg' 
                                : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                            }`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            {/* Bookings List */}
            {filteredBookings.length > 0 ? (
                <div className="space-y-6">
                    {filteredBookings.map(booking => {
                        const turf = turfs.find(t => t.id === booking.turfId);
                        return (
                            <div key={booking.id} className="bg-white dark:bg-brand-surface border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-sm hover:shadow-md transition-all group">
                                {/* Ticket Header */}
                                <div className="bg-slate-50 dark:bg-slate-800/50 p-4 flex justify-between items-center border-b border-slate-100 dark:border-slate-800">
                                    <div className="flex items-center">
                                        <span className={`w-2 h-2 rounded-full mr-2 ${
                                            booking.status === 'CONFIRMED' ? 'bg-emerald-500 animate-pulse' : 
                                            booking.status === 'CANCELLED' ? 'bg-slate-400' : 'bg-amber-500'
                                        }`}></span>
                                        <span className="font-black text-[10px] uppercase tracking-widest text-slate-600 dark:text-slate-300">
                                            {booking.status}
                                        </span>
                                    </div>
                                    <div className="flex items-center space-x-3">
                                        <span className="text-slate-400 text-[10px] font-mono font-bold tracking-tighter">REF: {booking.id}</span>
                                        {filter === 'Upcoming' && (
                                            <button 
                                                onClick={() => setShowCancelConfirm(booking.id)}
                                                className="text-slate-400 hover:text-red-500 transition-colors"
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        )}
                                    </div>
                                </div>

                                <div className="p-6">
                                    <div className="flex items-start mb-6">
                                        <div className="w-16 h-16 rounded-2xl bg-slate-100 dark:bg-slate-700 overflow-hidden mr-4 border border-slate-200 dark:border-slate-600 shadow-inner">
                                            <img src={turf?.image || 'https://images.unsplash.com/photo-1551958219-acbc608c6377?w=200'} className={`w-full h-full object-cover ${booking.status === 'CANCELLED' ? 'grayscale' : ''}`} />
                                        </div>
                                        <div className="flex-1">
                                            <h3 className="text-slate-900 dark:text-white font-black text-xl leading-tight mb-1 uppercase italic tracking-tighter">{booking.turfName}</h3>
                                            <p className="text-slate-500 text-xs flex items-center font-bold">
                                                <MapPin size={12} className="mr-1 text-brand-secondary" /> {turf?.location.split(',')[0] || 'Venue Location'}
                                            </p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Paid</p>
                                            <p className="text-slate-900 dark:text-white font-black text-sm">UGX {booking.price.toLocaleString()}</p>
                                        </div>
                                    </div>

                                    {/* Info Grid with Ticket Notches */}
                                    <div className="grid grid-cols-2 gap-3 mb-6 relative">
                                        <div className="bg-slate-50 dark:bg-slate-800/80 p-4 rounded-2xl border border-slate-100 dark:border-slate-700/50">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Match Date</p>
                                            <div className="flex items-center text-slate-900 dark:text-white font-bold text-sm">
                                                <Calendar size={14} className="mr-2 text-brand-secondary" />
                                                {booking.date}
                                            </div>
                                        </div>
                                        <div className="bg-slate-50 dark:bg-slate-800/80 p-4 rounded-2xl border border-slate-100 dark:border-slate-700/50">
                                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Kick Off</p>
                                            <div className="flex items-center text-slate-900 dark:text-white font-bold text-sm">
                                                <Clock size={14} className="mr-2 text-brand-secondary" />
                                                {booking.time}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex space-x-3">
                                        <button 
                                            onClick={() => setSelectedBooking(booking)}
                                            disabled={booking.status === 'CANCELLED'}
                                            className={`flex-[2] py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center shadow-lg active:scale-95 transition-all ${
                                                booking.status === 'CANCELLED' 
                                                ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 cursor-not-allowed' 
                                                : 'bg-brand-secondary text-white dark:text-black shadow-emerald-500/10'
                                            }`}
                                        >
                                            <QrCode size={18} className="mr-2" /> Digital Ticket
                                        </button>

                                        <div className="flex space-x-2">
                                            <button 
                                                onClick={() => handleShare(booking)}
                                                className="p-4 bg-slate-50 dark:bg-slate-800 text-slate-400 hover:text-brand-secondary rounded-2xl border border-slate-100 dark:border-slate-700 transition-colors"
                                            >
                                                <Share2 size={18} />
                                            </button>
                                            <button 
                                                onClick={() => openDirections(turf?.location || booking.turfName)}
                                                className="p-4 bg-slate-50 dark:bg-slate-800 text-slate-400 hover:text-brand-secondary rounded-2xl border border-slate-100 dark:border-slate-700 transition-colors"
                                            >
                                                <Navigation size={18} />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center py-24 text-center px-10 animate-fadeIn">
                    <div className="w-24 h-24 bg-slate-100 dark:bg-slate-900 rounded-[2rem] flex items-center justify-center mb-6 text-slate-300 dark:text-slate-800 border border-slate-200 dark:border-slate-800">
                        <History size={48} />
                    </div>
                    <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">
                        {searchTerm ? 'No matches found' : `No ${filter.toLowerCase()} bookings`}
                    </h3>
                    <p className="text-slate-500 text-sm mb-8 font-medium max-w-[220px]">
                        {searchTerm 
                            ? `Try searching for a different pitch or match name.` 
                            : `Time to hit the pitch! Explore elite turfs near you.`}
                    </p>
                    <button 
                        onClick={() => navigate('/home')}
                        className="bg-brand-secondary text-white dark:text-black px-10 py-4 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-emerald-500/20 active:scale-95 transition-all"
                    >
                        Find a Pitch
                    </button>
                </div>
            )}
        </div>
    </Layout>
  );
};

import React from 'react';
