// --- MOCK DATABASE FOR SEARCH FEATURE ---
const MOCK_USER_DATABASE = [
    { id: 'PL-8821', name: 'Ivan Ssemwanga', phone: '0772123456', avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop' },
    { id: 'PL-9932', name: 'John Doe', phone: '0755123456', avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop' },
    { id: 'PL-7741', name: 'Sarah K.', phone: '0701112233', avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop' },
    { id: 'PL-1029', name: 'Musa King', phone: '0788112233', avatar: 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=100&h=100&fit=crop' },
    { id: 'PL-3321', name: 'Alex Telles', phone: '0777998877', avatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop' },
];

interface Member {
    id: string;
    name: string;
    contact: string;
    isCaptain: boolean;
    hasPaid: boolean;
    avatar?: string;
    pitchlinkId?: string;
}

interface Team {
    id: string;
    name: string;
    members: Member[];
}

export const Teams: React.FC = () => {
  const navigate = useNavigate();
  const { bookings } = useBooking();

  // --- STATE ---
  const [teams, setTeams] = useState<Team[]>([
    {
      id: 't1',
      name: 'Kampala Kings',
      members: [
        { id: 'm1', name: 'David Okello', contact: '0772000000', isCaptain: true, hasPaid: true, pitchlinkId: 'PL-0001' },
        { id: 'm2', name: 'Mike Smith', contact: '0788112233', isCaptain: false, hasPaid: false, pitchlinkId: 'PL-1029' },
        { id: 'm3', name: 'Sarah Kibone', contact: '0701112233', isCaptain: false, hasPaid: true, pitchlinkId: 'PL-7741' },
      ]
    }
  ]);

  // Modal & Wizard State
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [createStep, setCreateStep] = useState(0); // 0: Name, 1: Add Players
  const [selectedTeamId, setSelectedTeamId] = useState<string | null>(null);

  // Form State
  const [newTeamName, setNewTeamName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [invitedMembers, setInvitedMembers] = useState<Member[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // --- ACTIONS ---

  const resetModal = () => {
      setShowCreateModal(false);
      setCreateStep(0);
      setNewTeamName('');
      setSearchQuery('');
      setInvitedMembers([]);
  };

  const handleSearch = (query: string) => {
      setSearchQuery(query);
      setIsSearching(true);
      // Simulate network delay for search
      setTimeout(() => setIsSearching(false), 300);
  };

  const filteredUsers = searchQuery.length > 2 
    ? MOCK_USER_DATABASE.filter(u => 
        (u.phone.includes(searchQuery) || u.id.toLowerCase().includes(searchQuery.toLowerCase())) &&
        !invitedMembers.some(m => m.pitchlinkId === u.id) // Exclude already invited
      )
    : [];

  const handleAddMember = (user: typeof MOCK_USER_DATABASE[0]) => {
      const newMember: Member = {
          id: Math.random().toString(36).substr(2, 9),
          name: user.name,
          contact: user.phone,
          isCaptain: false,
          hasPaid: false,
          avatar: user.avatar,
          pitchlinkId: user.id
      };
      setInvitedMembers([...invitedMembers, newMember]);
      setSearchQuery(''); // Clear search after adding
  };

  const handleRemoveMember = (pitchlinkId: string) => {
      setInvitedMembers(invitedMembers.filter(m => m.pitchlinkId !== pitchlinkId));
  };

  const handleCreateTeam = () => {
    if (!newTeamName.trim()) return;

    const captain: Member = { 
        id: 'me', 
        name: 'You (Captain)', 
        contact: '0770000000', 
        isCaptain: true, 
        hasPaid: true,
        pitchlinkId: 'PL-OWNR'
    };

    const newTeam: Team = {
      id: Math.random().toString(36).substr(2, 9),
      name: newTeamName,
      members: [captain, ...invitedMembers]
    };

    setTeams([...teams, newTeam]);
    resetModal();
  };

  const togglePayment = (teamId: string, memberId: string) => {
    setTeams(prev => prev.map(t => {
      if (t.id !== teamId) return t;
      return {
        ...t,
        members: t.members.map(m => m.id === memberId ? { ...m, hasPaid: !m.hasPaid } : m)
      };
    }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('Contact copied for MoMo payment!');
  };

  const shareToWhatsApp = (team: Team, booking?: any) => {
    const text = booking 
      ? `⚽ SQUAD CALL: Match at ${booking.turfName} on ${booking.date} @ ${booking.time}. Captain: ${team.members.find(m => m.isCaptain)?.name}. Please clear your fees via Footlink!`
      : `Hey! I've added you to the ${team.name} squad on Footlink. Check our next booking here.`;

    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  const getTeamBooking = (teamName: string) => {
    return bookings.find(b => b.userName.includes(teamName) || (teamName === 'Kampala Kings' && b.id === 'b1'));
  };

  return (
    <Layout>
      {showCreateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
          <div className="bg-white dark:bg-brand-surface w-full max-w-md rounded-[2.5rem] p-8 animate-slideUp overflow-hidden flex flex-col max-h-[90vh]">

            {/* Modal Header */}
            <div className="flex justify-between items-center mb-6">
              <div className="flex items-center">
                  {createStep === 1 && (
                      <button onClick={() => setCreateStep(0)} className="mr-3 p-2 bg-slate-100 dark:bg-slate-800 rounded-full">
                          <ArrowLeft size={20} />
                      </button>
                  )}
                  <div>
                    <h2 className="text-xl font-black uppercase italic text-slate-900 dark:text-white">
                        {createStep === 0 ? 'New Squad' : 'Draft Players'}
                    </h2>
                    <p className="text-xs text-slate-500">Step {createStep + 1} of 2</p>
                  </div>
              </div>
              <button onClick={resetModal}><X className="text-slate-400" /></button>
            </div>

            {/* STEP 0: TEAM NAME */}
            {createStep === 0 && (
                <div className="animate-fadeIn">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Team Identity</label>
                    <input 
                    type="text" 
                    autoFocus
                    placeholder="e.g. Ntinda Legends"
                    value={newTeamName}
                    onChange={(e) => setNewTeamName(e.target.value)}
                    className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-2xl p-4 text-lg font-bold mb-6 outline-none focus:ring-2 focus:ring-brand-secondary text-slate-900 dark:text-white"
                    />
                    <button 
                        onClick={() => {
                            if(newTeamName.trim()) setCreateStep(1);
                        }}
                        disabled={!newTeamName.trim()}
                        className="w-full bg-brand-secondary text-white dark:text-black py-4 rounded-xl font-black uppercase tracking-widest shadow-lg active:scale-95 transition-all disabled:opacity-50"
                    >
                    Next: Add Players
                    </button>
                </div>
            )}

            {/* STEP 1: ADD MEMBERS */}
            {createStep === 1 && (
                <div className="flex-1 flex flex-col min-h-0 animate-fadeIn">
                    {/* Search Bar */}
                    <div className="relative mb-4">
                        <Search className="absolute left-4 top-3.5 text-slate-400" size={20} />
                        <input 
                            type="text" 
                            autoFocus
                            placeholder="Phone (07...) or ID (PL-...)"
                            value={searchQuery}
                            onChange={(e) => handleSearch(e.target.value)}
                            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-3 pl-12 pr-4 text-sm font-bold outline-none focus:ring-2 focus:ring-brand-secondary text-slate-900 dark:text-white"
                        />
                        {isSearching && <Loader2 className="absolute right-4 top-3.5 animate-spin text-brand-secondary" size={20} />}
                    </div>

                    {/* Search Results */}
                    {searchQuery.length > 2 && (
                        <div className="mb-6 max-h-40 overflow-y-auto">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Search Results</p>
                            {filteredUsers.length > 0 ? (
                                <div className="space-y-2">
                                    {filteredUsers.map(user => (
                                        <div key={user.id} className="flex items-center justify-between p-2 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700">
                                            <div className="flex items-center">
                                                <img src={user.avatar} className="w-8 h-8 rounded-full object-cover mr-3" />
                                                <div>
                                                    <p className="text-sm font-bold text-slate-900 dark:text-white">{user.name}</p>
                                                    <p className="text-[10px] text-slate-500">{user.id} • {user.phone}</p>
                                                </div>
                                            </div>
                                            <button 
                                                onClick={() => handleAddMember(user)}
                                                className="p-2 bg-brand-secondary text-white dark:text-black rounded-lg hover:scale-105 transition-transform"
                                            >
                                                <UserPlus size={16} />
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-xs text-slate-500 italic p-2">No players found with that number or ID.</p>
                            )}
                        </div>
                    )}

                    {/* Invited List */}
                    <div className="flex-1 overflow-y-auto mb-4">
                         <div className="flex justify-between items-center mb-2">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Starting Lineup ({invitedMembers.length + 1})</p>
                            <span className="text-[10px] text-brand-secondary font-bold">You are Captain</span>
                         </div>

                         <div className="space-y-2">
                            {invitedMembers.map(member => (
                                <div key={member.pitchlinkId} className="flex items-center justify-between p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-800 animate-slideUp">
                                    <div className="flex items-center">
                                        <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-700 flex items-center justify-center text-slate-500 font-bold text-xs mr-3 overflow-hidden">
                                            {member.avatar ? <img src={member.avatar} className="w-full h-full object-cover"/> : member.name.charAt(0)}
                                        </div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-900 dark:text-white">{member.name}</p>
                                            <p className="text-[10px] text-brand-secondary">Pending Invite</p>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => handleRemoveMember(member.pitchlinkId!)}
                                        className="text-slate-400 hover:text-red-500 transition-colors"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            ))}
                            {invitedMembers.length === 0 && (
                                <div className="p-4 border-2 border-dashed border-slate-200 dark:border-slate-700 rounded-xl text-center">
                                    <p className="text-xs text-slate-400">Search above to add teammates.</p>
                                </div>
                            )}
                         </div>
                    </div>

                    <button 
                        onClick={handleCreateTeam}
                        className="w-full bg-brand-secondary text-white dark:text-black py-4 rounded-xl font-black uppercase tracking-widest shadow-lg active:scale-95 transition-all"
                    >
                        Create Team & Send Invites
                    </button>
                </div>
            )}
          </div>
        </div>
      )}

      <div className="p-5 pt-8 bg-slate-50 dark:bg-brand-dark min-h-screen pb-32">
        <div className="flex justify-between items-center mb-8">
          <div>
            <h1 className="text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">Teams</h1>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-2">Logistics & Roster</p>
          </div>
          <div className="flex space-x-2">
            <button 
                onClick={() => navigate('/squad-finder')}
                className="bg-white dark:bg-slate-800 text-slate-900 dark:text-white p-3 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 active:scale-95 transition-transform"
                title="Find Players"
            >
                <Target size={24} />
            </button>
            <button 
                onClick={() => setShowCreateModal(true)}
                className="bg-brand-secondary text-white dark:text-black p-3 rounded-2xl shadow-xl active:scale-95 transition-transform"
                title="Create Team"
            >
                <Plus size={24} />
            </button>
          </div>
        </div>

        <div className="space-y-6">
          {teams.map(team => {
            const activeBooking = getTeamBooking(team.name);
            const isDetailed = selectedTeamId === team.id;
            const paidCount = team.members.filter(m => m.hasPaid).length;
            const collectionProgress = (paidCount / team.members.length) * 100;

            return (
              <div key={team.id} className="bg-white dark:bg-brand-surface border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-sm transition-all border-b-4 border-b-slate-200 dark:border-b-slate-800">
                <div className="p-6">
                  <div className="flex justify-between items-start mb-6">
                    <div onClick={() => setSelectedTeamId(isDetailed ? null : team.id)} className="cursor-pointer">
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">{team.name}</h2>
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest flex items-center mt-1">
                        <Users size={12} className="mr-1 text-brand-secondary" /> {team.members.length} Players
                      </p>
                    </div>
                    <button 
                      onClick={() => shareToWhatsApp(team, activeBooking)}
                      className="p-3 bg-emerald-500/10 text-emerald-600 rounded-2xl border border-emerald-500/20 active:scale-95 transition-all"
                    >
                      <MessageCircle size={20} />
                    </button>
                  </div>

                  {/* Collection Progress */}
                  <div className="mb-6">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Collection Progress</span>
                        <span className="text-[10px] font-black text-brand-secondary uppercase">{paidCount}/{team.members.length} Paid</span>
                    </div>
