export const generateMatchDetails = async (
  type: string,
  venueName: string,
  paymentMode: string
): Promise<{ title: string; description: string }> => {
  // Simulate network latency (1.5s)
  await new Promise((resolve) => setTimeout(resolve, 1500));

  const adjectives = ['High-Intensity', 'Casual', 'Late Night', 'Weekend', 'Competitive', 'Friendly'];
  const adj = adjectives[Math.floor(Math.random() * adjectives.length)];

  const paymentText = paymentMode === 'Split' 
    ? "Cost is split evenly among players." 
    : "Organizer has covered the venue fees.";

  // Mock Logic to generate realistic text based on inputs
  const title = `${adj} ${type} at ${venueName}`;
  const description = `Join us for a ${type.toLowerCase()} match at ${venueName}. We are looking for reliable players to fill the squad. ${paymentText} Bring your A-game!`;

  return {
    title,
    description
  };
};

export interface ChatMessage {
    role: 'user' | 'model';
    text: string;
}

export const generateChatResponse = async (
  message: string,
  history: ChatMessage[]
): Promise<string> => {
    // Simulate thinking time
    await new Promise((resolve) => setTimeout(resolve, 1000));

    const lowerMsg = message.toLowerCase();

    // Simple keyword matching to simulate AI context awareness
    if (lowerMsg.includes('turf') || lowerMsg.includes('field') || lowerMsg.includes('pitch')) {
        return "Based on popular ratings, I recommend Fast Sports Fusion in Bugolobi or Lugogo Futsal Arena. Both have excellent floodlights and parking.";
    }

    if (lowerMsg.includes('price') || lowerMsg.includes('cost') || lowerMsg.includes('pay')) {
        return "Prices for 5-a-side turfs in Kampala typically range from UGX 35,000 to UGX 50,000 per hour. Peak hours (6 PM - 9 PM) might be slightly higher.";
    }

    if (lowerMsg.includes('tactic') || lowerMsg.includes('formation')) {
        return "For 5-a-side, the 1-2-1 formation (The Diamond) offers the best balance. It ensures you have cover at the back while maintaining width in attack.";
    }

    if (lowerMsg.includes('team') || lowerMsg.includes('squad')) {
        return "You can use the 'Teams' tab to manage your roster. Don't forget to send invite links via WhatsApp to ensure everyone pays their share on time.";
    }

    // Default generic response
    return "That sounds like a great plan! I'm here to help you organize matches, find venues, or discuss tactics. What else do you need assistance with?";
};

