export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking(); 
  const { addXP, stats } = useUser();

  // UI States
  const [isScanning, setIsScanning] = useState(false);

  // Create Match Full Page State
  const [isCreating, setIsCreating] = useState(false);
  const [createStep, setCreateStep] = useState(0); 

  // Create Match Local State
  const [turfSearchQuery, setTurfSearchQuery] = useState("");
  const [newMatch, setNewMatch] = useState({
      type: 'Friendly',
      format: '5-a-side',
      duration: 1, // Hours
      venueId: '',
      date: new Date().toISOString().split('T')[0],
      time: '',
      paymentMode: 'Split',
      notes: ''
  });

  // Data States
  const [communityMatches, setCommunityMatches] = useState<CommunityMatch[]>([
      {
          id: 'cm1',
          title: 'Sunday Morning Sweat',
          description: 'Casual game to start the day. Beginners welcome!',
          organizer: 'Coach Mike',
          organizerAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop',
          venue: turfs[0],
          date: '2025-01-20',
          time: '08:00',
          format: '5-a-side',
          joined: 7,
          maxPlayers: 10,
          costPerPerson: 5000,
          type: 'Friendly',
          hasJoined: false
      },
      {
          id: 'cm2',
          title: 'Competitive 7v7',
          description: 'High intensity match. Bring your A-game.',
          organizer: 'Sarah K.',
          organizerAvatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop',
          venue: turfs[2],
          date: '2025-01-20',
          time: '19:00',
          format: '7-a-side',
          joined: 12,
          maxPlayers: 14,
          costPerPerson: 8000,
          type: 'Competitive',
          hasJoined: false
      }
  ]);

  const myTeam = MY_TEAMS[0];

  // --- HELPERS ---
  const hasActiveMatch = useMemo(() => communityMatches.some(m => m.hasJoined), [communityMatches]);

  // Filter Turfs for Search
  const filteredTurfs = useMemo(() => {
      if (!turfSearchQuery) return turfs;
      return turfs.filter(t => 
          t.name.toLowerCase().includes(turfSearchQuery.toLowerCase()) ||
          t.location.toLowerCase().includes(turfSearchQuery.toLowerCase())
      );
  }, [turfs, turfSearchQuery]);

  // Dynamic Time Slots based on Venue Hours + Duration Availability
  const getAvailableSlots = (turfId: string, date: string, duration: number) => {
      const turf = turfs.find(t => t.id === turfId);
      if (!turf) return [];

      const startHour = parseInt(turf.openingHour.split(':')[0]);
      const endHour = parseInt(turf.closingHour.split(':')[0]);
      const slots = [];

      // Check if date is blocked
      if (turf.blockedDates.includes(date)) return [];

      for (let i = startHour; i <= endHour - duration; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          // Check if ANY hour in the duration is booked
          let isBlocked = false;
          for (let d = 0; d < duration; d++) {
             const checkTime = `${(i + d).toString().padStart(2, '0')}:00`;
             const booked = bookings.some(b => 
                b.turfId === turfId && 
                b.date === date && 
                b.time === checkTime &&
                b.status !== 'CANCELLED'
             );
             if (booked) isBlocked = true;
          }

          if (!isBlocked) slots.push(time);
      }
      return slots;
  };

  // --- ACTIONS ---

  const handleJoinMatch = (matchId: string) => {
      // Prevent joining if already in a match
      if (hasActiveMatch) return;

      setCommunityMatches(prev => prev.map(m => {
          if (m.id === matchId && !m.hasJoined && m.joined < m.maxPlayers) {
              addXP(50); // Join Bonus
              return { ...m, joined: m.joined + 1, hasJoined: true };
          }
          return m;
      }));
  };

  const handleCreateSubmit = async () => {
      if (hasActiveMatch) return;
      setIsScanning(true); 

      const selectedTurf = turfs.find(t => t.id === newMatch.venueId) || turfs[0];
      const maxP = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create System Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. AI Gen Title & Description (Mocked for Frontend MVP)
      // FUTURE TODO: Move this logic to backend API to use actual GenAI SDK safely.
      let aiTitle = `${newMatch.type} at ${selectedTurf.name}`;
      let aiDesc = newMatch.notes || "Join us for a great game!";

      if (!newMatch.notes) {
          try {
              // Using local mock function instead of direct API call
              const result = await generateMatchDetails(newMatch.type, selectedTurf.name, newMatch.paymentMode);
              aiTitle = result.title;
              aiDesc = result.description;
          } catch (e) { console.error("Mock AI Generation failed", e); }
      }

      const newCommunityMatch: CommunityMatch = {
          id: bookingId,
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
          venue: selectedTurf,
          date: newMatch.date,
