          joined: 1,
          maxPlayers: maxP,
          costPerPerson: costPerPerson,
          type: newMatch.type as any,
          hasJoined: true // Creator joins automatically
      };

      setTimeout(() => {
          setCommunityMatches(prev => [newCommunityMatch, ...prev]);
          setIsScanning(false);
          addXP(200);
          setIsCreating(false); 
          setNewMatch({ ...newMatch, time: '', venueId: '', notes: '' });
          setCreateStep(0);
      }, 500); // Small delay to smooth transition
  };

  const renderCreateMatchPage = () => {
    const selectedTurf = turfs.find(t => t.id === newMatch.venueId);
