    if (isScanning) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[80vh] bg-slate-50 dark:bg-brand-dark p-5">
                <div className="relative">
                    <div className="w-24 h-24 rounded-full border-4 border-slate-200 dark:border-slate-700 animate-spin border-t-brand-secondary"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-brand-secondary animate-pulse" size={32} />
                    </div>
                </div>
                <h2 className="mt-8 text-2xl font-bold text-slate-900 dark:text-white">Organizing Match...</h2>
