import React, { useState, useRef, useEffect } from 'react';
// REMOVED: import { GoogleGenAI } from "@google/genai"; -> Replaced with Mock Utility
import { generateChatResponse, ChatMessage } from '../utils/mockAI';
import { Send, X, Sparkles, Bot, User, Loader2 } from 'lucide-react';
import { TURFS } from '../constants';

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
}

export const AIChat: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { id: 'init', role: 'model', text: "Hi! I'm Coach Gemini. I can help you find turfs, suggest tactics, or organize your team. What's the plan?" }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      // FUTURE TODO: Move this logic to backend API to use actual GenAI SDK safely.
      // Current implementation uses a mock utility for frontend demonstration.

      const history: ChatMessage[] = messages.map(m => ({
          role: m.role,
          text: m.text
      }));

      const responseText = await generateChatResponse(userMessage.text, history);

      const modelMsgId = (Date.now() + 1).toString();
      // Add placeholder
      setMessages(prev => [...prev, { id: modelMsgId, role: 'model', text: '' }]);

      // Simulate streaming effect for UI fidelity
      const words = responseText.split(' ');
      let currentText = '';

      for (const word of words) {
          currentText += word + ' ';
          setMessages(prev => prev.map(m => 
              m.id === modelMsgId ? { ...m, text: currentText } : m
          ));
          // Tiny delay to look like typing
          await new Promise(r => setTimeout(r, 50)); 
      }

    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { id: 'error', role: 'model', text: "Sorry, I'm having trouble connecting to the locker room (server error). Try again!" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center pointer-events-none">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm pointer-events-auto" onClick={onClose} />

      {/* Chat Window */}
      <div className="bg-slate-50 dark:bg-slate-900 w-full sm:w-[400px] h-[85vh] sm:h-[600px] rounded-t-3xl sm:rounded-2xl shadow-2xl flex flex-col pointer-events-auto overflow-hidden animate-slideUp border border-slate-200 dark:border-slate-700">

        {/* Header */}
        <div className="bg-white dark:bg-slate-800 p-4 flex items-center justify-between border-b border-slate-200 dark:border-slate-700">
          <div className="flex items-center">
            <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-brand-primary to-blue-500 flex items-center justify-center mr-3 shadow-lg">
              <Bot className="text-white" size={24} />
            </div>
            <div>
              <h3 className="font-bold text-slate-900 dark:text-white">Coach Gemini</h3>
              <p className="text-xs text-brand-secondary font-medium flex items-center">
                <span className="w-2 h-2 rounded-full bg-brand-secondary mr-1 animate-pulse" /> Online
              </p>
            </div>
          </div>
