import React, { useEffect, useState } from 'react';
import { OwnerService } from '../../services/owner';
import { Payout, Transaction } from '../../types';
import { Wallet, ArrowUpRight, ArrowDownLeft, Download, Loader2 } from 'lucide-react';

export const FinanceManager: React.FC = () => {
    const [finance, setFinance] = useState<{balance: number, transactions: Transaction[], payouts: Payout[]} | null>(null);
    const [requesting, setRequesting] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        const data = await OwnerService.getFinancials();
        setFinance(data);
    };

    const handlePayout = async () => {
        if (!finance || finance.balance < 50000) return;
        setRequesting(true);
        await OwnerService.requestPayout(finance.balance);
        await loadData(); // Refresh
        setRequesting(false);
        alert("Payout request submitted.");
    };

    if (!finance) return <div className="p-10 text-center animate-pulse">Loading financial data...</div>;

    return (
        <div className="space-y-8 animate-fadeIn">
            {/* Wallet Card */}
            <div className="bg-gradient-to-br from-slate-900 to-slate-800 dark:from-indigo-900 dark:to-slate-900 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-5">
                    <Wallet size={200} />
                </div>

                <div className="relative z-10">
                    <p className="text-[10px] font-bold uppercase tracking-widest opacity-70 mb-2">Available Balance</p>
                    <h1 className="text-5xl font-black mb-8 tracking-tighter">UGX {finance.balance.toLocaleString()}</h1>

                    <div className="flex gap-4">
                        <button 
                            onClick={handlePayout}
                            disabled={finance.balance < 50000 || requesting}
                            className="bg-white text-slate-900 px-6 py-3 rounded-xl font-bold text-sm flex items-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-100 transition-colors"
                        >
                            {requesting ? <Loader2 className="animate-spin mr-2" size={18}/> : <ArrowUpRight className="mr-2" size={18}/>}
                            Request Payout
                        </button>
                        <div className="text-[10px] self-center opacity-60 font-medium">
                            Min. withdrawal: UGX 50,000<br/>Fee: 10% Platform Commission
                        </div>
                    </div>
                </div>
            </div>

            {/* Payout History */}
            <div>
                <h3 className="font-bold text-slate-900 dark:text-white mb-4">Payout Requests</h3>
                <div className="space-y-3">
                    {finance.payouts.length === 0 && <p className="text-sm text-slate-400 italic">No past payouts.</p>}
                    {finance.payouts.map(po => (
                        <div key={po.id} className="bg-white dark:bg-slate-800 p-4 rounded-2xl flex justify-between items-center border border-slate-100 dark:border-slate-700">
                            <div>
                                <p className="font-bold text-slate-900 dark:text-white">UGX {po.amount.toLocaleString()}</p>
                                <p className="text-xs text-slate-500">{new Date(po.requestDate).toLocaleDateString()}</p>
                            </div>
                            <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${
                                po.status === 'PAID' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'
                            }`}>
                                {po.status}
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Transactions */}
            <div>
                <div className="flex justify-between items-center mb-4">
                    <h3 className="font-bold text-slate-900 dark:text-white">Recent Earnings</h3>
                    <button className="text-xs font-bold text-brand-secondary flex items-center"><Download size={14} className="mr-1"/> Export CSV</button>
                </div>
                <div className="bg-white dark:bg-slate-800 rounded-3xl p-2 border border-slate-200 dark:border-slate-700">
                    {finance.transactions.map(txn => (
                        <div key={txn.id} className="p-4 border-b border-slate-100 dark:border-slate-700 last:border-0 flex justify-between items-center">
                            <div className="flex items-center">
                                <div className="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-900/20 text-emerald-500 flex items-center justify-center mr-3">
                                    <ArrowDownLeft size={18} />
                                </div>
                                <div>
                                    <p className="font-bold text-sm text-slate-900 dark:text-white">{txn.description}</p>
                                    <p className="text-[10px] text-slate-500">{txn.date}</p>
                                </div>
                            </div>
                            <span className="font-mono font-bold text-emerald-600">+ {txn.amount.toLocaleString()}</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

