import React, { createContext, useContext, useState, useEffect } from 'react';
import { Turf, Booking } from '../types';
import { TURFS } from '../constants';

const INITIAL_BOOKINGS: Booking[] = [
    {
        id: 'B-LOCAL-01',
        turfId: '1',
        turfName: 'Fast Sports Fusion',
        userName: 'David Okello',
        date: new Date().toISOString().split('T')[0], // Today
        time: '18:00',
        duration: 1,
        status: 'CONFIRMED',
        price: 50000,
        createdAt: new Date().toISOString(),
        paymentStatus: 'PAID'
    }
];

interface BookingContextType {
  turfs: Turf[];
  bookings: Booking[];
  updateTurf: (id: string, updates: Partial<Turf>) => void;
  addTurf: (turf: Turf) => void;
  deleteTurf: (id: string) => void;
  addBooking: (booking: Booking) => void;
  updateBookingStatus: (id: string, status: Booking['status']) => void;
  toggleBlockDate: (turfId: string, date: string) => void;
}

const BookingContext = createContext<BookingContextType | undefined>(undefined);

export const BookingProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [turfs, setTurfs] = useState<Turf[]>(TURFS);
  const [bookings, setBookings] = useState<Booking[]>(() => {
    const saved = localStorage.getItem('footlink_bookings');
    return saved ? JSON.parse(saved) : INITIAL_BOOKINGS;
  });

  useEffect(() => {
    localStorage.setItem('footlink_bookings', JSON.stringify(bookings));
  }, [bookings]);

  const updateTurf = (id: string, updates: Partial<Turf>) => {
    setTurfs(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const addTurf = (turf: Turf) => {
    setTurfs(prev => [turf, ...prev]);
  };

  const deleteTurf = (id: string) => {
    setTurfs(prev => prev.filter(t => t.id !== id));
  };

  const addBooking = (booking: Booking) => {
    setBookings(prev => [booking, ...prev]);
  };

  const updateBookingStatus = (id: string, status: Booking['status']) => {
    setBookings(prev => prev.map(b => b.id === id ? { ...b, status } : b));
  };

  const toggleBlockDate = (turfId: string, date: string) => {
      setTurfs(prev => prev.map(t => {
          if (t.id !== turfId) return t;
          const isBlocked = t.blockedDates.includes(date);
          const newBlocked = isBlocked 
             ? t.blockedDates.filter(d => d !== date)
             : [...t.blockedDates, date];
          return { ...t, blockedDates: newBlocked };
      }));
  };

  return (
    <BookingContext.Provider value={{ turfs, bookings, updateTurf, addTurf, deleteTurf, addBooking, updateBookingStatus, toggleBlockDate }}>
      {children}
    </BookingContext.Provider>
  );
};

export const useBooking = () => {
  const context = useContext(BookingContext);
  if (context === undefined) {
    throw new Error('useBooking must be used within a BookingProvider');
  }
  return context;
};

import { Booking, Payout, StaffMember, Transaction, Turf } from '../types';
import { TURFS, MY_BOOKINGS } from '../constants';

// --- MOCK DATABASE STATE ---
// In a real app, this would be your Postgres/Supabase database.
let mockTurfs: Turf[] = TURFS.map(t => ({ ...t }));
let mockBookings: Booking[] = MY_BOOKINGS.map(b => ({ ...b }));
let mockStaff: StaffMember[] = [
    { id: 's1', name: 'Musa Kato', role: 'MANAGER', phone: '0771234567', avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100' },
    { id: 's2', name: 'John Bukenya', role: 'CARETAKER', phone: '0789012345' }
];
let mockPayouts: Payout[] = [];

// --- SERVICE METHODS ---

export const OwnerService = {
    // 1. Dashboard Overview
    getDashboardStats: async () => {
        await new Promise(r => setTimeout(r, 600)); // Simulate latency

        const today = new Date().toISOString().split('T')[0];
        const todaysBookings = mockBookings.filter(b => b.date === today && b.status !== 'CANCELLED');
        const revenue = todaysBookings.reduce((sum, b) => sum + b.price, 0);

        // Mock Occupancy Calculation
        const totalSlots = mockTurfs.length * 12; // 12 hours open
        const bookedSlots = todaysBookings.length;
        const occupancy = Math.round((bookedSlots / totalSlots) * 100) || 0;

        return {
            todayRevenue: revenue,
            todayBookingsCount: todaysBookings.length,
            occupancyRate: occupancy,
            pendingRequests: mockBookings.filter(b => b.status === 'PENDING').length
        };
    },

    // 2. Facilities Management
    getPitches: async (): Promise<Turf[]> => {
        await new Promise(r => setTimeout(r, 500));
        return mockTurfs;
    },

    updatePitchStatus: async (id: string, status: 'ACTIVE' | 'MAINTENANCE' | 'CLOSED') => {
        await new Promise(r => setTimeout(r, 500));
        mockTurfs = mockTurfs.map(t => t.id === id ? { ...t, status } : t);
        return true;
    },

    // 3. Bookings
    getBookings: async (filter?: string): Promise<Booking[]> => {
        await new Promise(r => setTimeout(r, 400));
        if (filter === 'TODAY') {
             const today = new Date().toISOString().split('T')[0];
             return mockBookings.filter(b => b.date === today);
        }
        return mockBookings.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    },

    updateBookingStatus: async (id: string, status: Booking['status']) => {
        await new Promise(r => setTimeout(r, 600)); // Network delay
        mockBookings = mockBookings.map(b => b.id === id ? { ...b, status } : b);
        return true;
    },

    // 4. Staff
    getStaff: async (): Promise<StaffMember[]> => {
        await new Promise(r => setTimeout(r, 300));
        return mockStaff;
    },

    addStaff: async (staff: StaffMember) => {
        await new Promise(r => setTimeout(r, 800));
        mockStaff.push(staff);
        return staff;
    },

    // 5. Finance
    getFinancials: async () => {
        await new Promise(r => setTimeout(r, 500));
        const totalRevenue = mockBookings
            .filter(b => b.status === 'CONFIRMED' || b.status === 'COMPLETED')
            .reduce((sum, b) => sum + b.price, 0);

        const platformFee = totalRevenue * 0.1; // 10% fee
        const netEarnings = totalRevenue - platformFee;

        // Mock Transaction History
        const transactions: Transaction[] = mockBookings
            .filter(b => b.status === 'CONFIRMED')
            .slice(0, 10)
            .map(b => ({
