export const FacilityManager: React.FC = () => {
    const [pitches, setPitches] = useState<Turf[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAdding, setIsAdding] = useState(false);

    useEffect(() => {
        loadPitches();
    }, []);

    const loadPitches = async () => {
        const data = await OwnerService.getPitches();
        setPitches(data);
        setLoading(false);
    };

    const handleAddPitch = async () => {
        const name = window.prompt("Enter Pitch Name:");
        if (!name) return;

        setIsAdding(true);
        // Add a mock pitch
        await OwnerService.addTurf({ name });
        await loadPitches();
        setIsAdding(false);
    };

    const toggleStatus = async (id: string, currentStatus: string) => {
        // BACKEND: API call to update turf status
        const newStatus = currentStatus === 'ACTIVE' ? 'MAINTENANCE' : 'ACTIVE';
        setPitches(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
        await OwnerService.updatePitchStatus(id, newStatus);
    };

    if (loading) return <div className="p-10 text-center text-slate-400">Loading facilities...</div>;

    return (
        <div className="space-y-6 animate-fadeIn">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-black italic uppercase text-slate-900 dark:text-white">Your Pitches</h2>
                <button 
                    onClick={handleAddPitch}
                    disabled={isAdding}
                    className="bg-brand-secondary text-white px-4 py-3 rounded-xl flex items-center text-xs font-bold uppercase shadow-lg active:scale-95 transition-transform disabled:opacity-50"
                >
                    {isAdding ? <Loader2 className="animate-spin mr-2" size={16}/> : <Plus size={16} className="mr-2" />}
                    Add Pitch
                </button>
            </div>

            <div className="grid grid-cols-1 gap-4">
                {pitches.map(pitch => (
                    <div key={pitch.id} className="bg-white dark:bg-slate-800 p-4 rounded-3xl border border-slate-200 dark:border-slate-700 flex flex-col md:flex-row items-center gap-6 shadow-sm">
                        <div className="w-full md:w-32 h-32 rounded-2xl overflow-hidden bg-slate-200 relative">
                            <img src={pitch.image} className={`w-full h-full object-cover transition-all ${pitch.status !== 'ACTIVE' ? 'grayscale' : ''}`} />
                            <div className={`absolute top-2 left-2 px-2 py-1 rounded-lg text-[10px] font-black uppercase ${
                                pitch.status === 'ACTIVE' ? 'bg-emerald-500 text-white' : 'bg-slate-900 text-white'
                            }`}>
                                {pitch.status}
                            </div>
                        </div>

                        <div className="flex-1 text-center md:text-left">
                            <h3 className="text-lg font-black text-slate-900 dark:text-white uppercase italic">{pitch.name}</h3>
                            <p className="text-slate-500 text-xs flex items-center justify-center md:justify-start mt-1">
                                <MapPin size={12} className="mr-1" /> {pitch.location}
                            </p>
                            <div className="flex gap-4 mt-4 justify-center md:justify-start text-xs">
                                <div>
                                    <span className="block text-slate-400 font-bold uppercase text-[10px]">Price</span>
                                    <span className="font-bold text-slate-900 dark:text-white">UGX {pitch.pricePerHour.toLocaleString()}</span>
                                </div>
                                <div>
                                    <span className="block text-slate-400 font-bold uppercase text-[10px]">Type</span>
                                    <span className="font-bold text-slate-900 dark:text-white">5-a-side</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex gap-2 w-full md:w-auto">
                            <button className="flex-1 md:flex-none p-3 bg-slate-100 dark:bg-slate-700 rounded-xl text-slate-600 dark:text-slate-300 hover:text-brand-secondary transition-colors">
                                <Edit2 size={18} />
                            </button>
                            <button 
                                onClick={() => toggleStatus(pitch.id, pitch.status)}
                                className={`flex-1 md:flex-none p-3 rounded-xl transition-colors ${
                                    pitch.status === 'ACTIVE' 
                                    ? 'bg-red-50 text-red-500 hover:bg-red-100' 
                                    : 'bg-emerald-50 text-emerald-500 hover:bg-emerald-100'
                                }`}
                                title={pitch.status === 'ACTIVE' ? 'Set to Maintenance' : 'Activate'}
                            >
                                <Power size={18} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

