// In a real app, this would be your Postgres/Supabase database.
let mockTurfs: Turf[] = TURFS.map(t => ({ ...t }));
let mockBookings: Booking[] = MY_BOOKINGS.map(b => ({ ...b }));
let mockStaff: StaffMember[] = [
    { id: 's1', name: 'Musa Kato', role: 'MANAGER', phone: '0771234567', avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100' },
    { id: 's2', name: 'John Bukenya', role: 'CARETAKER', phone: '0789012345' }
];
let mockPayouts: Payout[] = [];

let mockProfile: BusinessProfile = {
    businessName: 'Kampala Arena',
    contactEmail: 'admin@kampalaarena.com',
    contactPhone: '0772123456',
    mobileMoneyNumber: '0772123456',
    operatingHours: { open: '08:00', close: '23:00' }
};

// --- SERVICE METHODS ---

export const OwnerService = {
    // 1. Dashboard Overview
    getDashboardStats: async () => {
        await new Promise(r => setTimeout(r, 600)); // Simulate latency

        const today = new Date().toISOString().split('T')[0];
        const todaysBookings = mockBookings.filter(b => b.date === today && b.status !== 'CANCELLED');
        const revenue = todaysBookings.reduce((sum, b) => sum + b.price, 0);

        // Mock Occupancy Calculation
        const totalSlots = mockTurfs.length * 12; // 12 hours open
        const bookedSlots = todaysBookings.length;
        const occupancy = Math.round((bookedSlots / totalSlots) * 100) || 0;

        return {
            todayRevenue: revenue,
            todayBookingsCount: todaysBookings.length,
            occupancyRate: occupancy,
            pendingRequests: mockBookings.filter(b => b.status === 'PENDING').length
        };
    },

    // 2. Facilities Management
    getPitches: async (): Promise<Turf[]> => {
        await new Promise(r => setTimeout(r, 500));
        return mockTurfs;
    },

    updatePitchStatus: async (id: string, status: 'ACTIVE' | 'MAINTENANCE' | 'CLOSED') => {
        await new Promise(r => setTimeout(r, 500));
        mockTurfs = mockTurfs.map(t => t.id === id ? { ...t, status } : t);
        return true;
    },

    addTurf: async (turf: Partial<Turf>): Promise<Turf> => {
        await new Promise(r => setTimeout(r, 800));
        const newTurf: Turf = {
            id: `turf-${Date.now()}`,
            name: turf.name || 'New Pitch',
            location: turf.location || 'Kampala',
            rating: 5.0,
            pricePerHour: 50000,
            image: 'https://images.unsplash.com/photo-1529900748604-07564a03e7a6?w=800',
            amenities: ['Lighting', 'Parking'],
            distance: '0 km',
            openingHour: '08:00',
            closingHour: '23:00',
            blockedDates: [],
            isVerified: false,
            status: 'ACTIVE',
            coordinates: [0.3476, 32.5825],
            ...turf
        };
        mockTurfs.push(newTurf);
        return newTurf;
    },

    updateTurfDetails: async (id: string, updates: Partial<Turf>) => {
        await new Promise(r => setTimeout(r, 500));
        mockTurfs = mockTurfs.map(t => t.id === id ? { ...t, ...updates } : t);
        return true;
    },

    // 3. Bookings
    getBookings: async (filter?: string): Promise<Booking[]> => {
        await new Promise(r => setTimeout(r, 400));
        if (filter === 'TODAY') {
             const today = new Date().toISOString().split('T')[0];
             return mockBookings.filter(b => b.date === today);
        }
        return mockBookings.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    },

    updateBookingStatus: async (id: string, status: Booking['status']) => {
        await new Promise(r => setTimeout(r, 600)); // Network delay
        mockBookings = mockBookings.map(b => b.id === id ? { ...b, status } : b);
        return true;
    },

    // 4. Staff
    getStaff: async (): Promise<StaffMember[]> => {
        await new Promise(r => setTimeout(r, 300));
        return mockStaff;
    },

    addStaff: async (staff: StaffMember) => {
        await new Promise(r => setTimeout(r, 800));
        mockStaff.push(staff);
        return staff;
    },

    deleteStaff: async (id: string) => {
        await new Promise(r => setTimeout(r, 500));
        mockStaff = mockStaff.filter(s => s.id !== id);
        return true;
    },

    // 5. Finance
    getFinancials: async () => {
        await new Promise(r => setTimeout(r, 500));
        const totalRevenue = mockBookings
            .filter(b => b.status === 'CONFIRMED' || b.status === 'COMPLETED')
            .reduce((sum, b) => sum + b.price, 0);

        const platformFee = totalRevenue * 0.1; // 10% fee
        const netEarnings = totalRevenue - platformFee;

        // Mock Transaction History
        const transactions: Transaction[] = mockBookings
            .filter(b => b.status === 'CONFIRMED')
            .slice(0, 10)
            .map(b => ({
                id: `txn-${b.id}`,
                bookingId: b.id,
                type: 'CREDIT',
                amount: b.price * 0.9, // Net after fee
                description: `Booking: ${b.turfName}`,
                date: b.date
            }));

        return {
            balance: netEarnings,
            totalRevenue,
            transactions,
            payouts: mockPayouts
        };
    },

    requestPayout: async (amount: number) => {
        await new Promise(r => setTimeout(r, 1000));
        const newPayout: Payout = {
            id: `po-${Date.now()}`,
            amount,
            status: 'PENDING',
            requestDate: new Date().toISOString(),
            method: 'MOBILE_MONEY'
        };
        mockPayouts.push(newPayout);
        return newPayout;
    },

    // 6. Settings
    getBusinessProfile: async (): Promise<BusinessProfile> => {
        await new Promise(r => setTimeout(r, 400));
        return mockProfile;
    },

    updateBusinessProfile: async (profile: BusinessProfile) => {
        await new Promise(r => setTimeout(r, 1000));
        mockProfile = profile;
        return profile;
    }
};

