        loadPitches();
    }, []);

    const loadPitches = async () => {
        const data = await OwnerService.getPitches();
        setPitches(data);
        setLoading(false);
    };

    const handleAddPitch = async () => {
        const name = window.prompt("Enter Pitch Name:");
