        setIsAdding(true);
        // Add a mock pitch
        await OwnerService.addTurf({ name });
        await loadPitches();
        setIsAdding(false);
    };

    const handleEditPitch = async (pitch: Turf) => {
        const newPrice = window.prompt(`Enter new price for ${pitch.name} (Current: ${pitch.pricePerHour}):`, pitch.pricePerHour.toString());
        if (newPrice && !isNaN(Number(newPrice))) {
            const price = Number(newPrice);
            // Optimistic update
            setPitches(prev => prev.map(p => p.id === pitch.id ? { ...p, pricePerHour: price } : p));
            await OwnerService.updateTurfDetails(pitch.id, { pricePerHour: price });
