        // BACKEND: API call to update turf status
        const newStatus = currentStatus === 'ACTIVE' ? 'MAINTENANCE' : 'ACTIVE';
        setPitches(prev => prev.map(p => p.id === id ? { ...p, status: newStatus } : p));
