                <div className="h-48 w-full rounded-2xl overflow-hidden mb-4 border border-slate-200 dark:border-slate-800 shadow-inner z-0">
                    <MapContainer 
                        center={turf.coordinates || [0.33, 32.60]} 
                        zoom={15} 
                        scrollWheelZoom={false}
                        dragging={false}
                        zoomControl={false}
                        style={{ height: '100%', width: '100%' }}
                    >
                        <TileLayer
                            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
                        />
                        <Marker position={turf.coordinates || [0,0]} icon={emeraldIcon} />
                    </MapContainer>
                </div>
                <button 
                  onClick={openDirections}
                  className="w-full py-3 bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white rounded-xl text-xs font-black uppercase tracking-[0.2em] flex items-center justify-center hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
                >
                    <Navigation size={14} className="mr-2 text-brand-secondary" /> Get Directions
                </button>
            </div>

            <div className="bg-white dark:bg-brand-surface p-5 rounded-2xl border border-slate-200 dark:border-slate-700 mb-6 shadow-sm">
                <h3 className="text-slate-900 dark:text-white font-bold mb-2">Facility Insights</h3>
                <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-4">Highly rated for its {turf.amenities[0]} and {turf.amenities[1]}. Perfect for competitive tournament play.</p>

                <div className="grid grid-cols-2 gap-3">
                    {turf.amenities.map(a => (
                        <div key={a} className="bg-slate-50 dark:bg-slate-700/50 border border-slate-100 dark:border-slate-700 p-2 rounded-xl flex items-center">
                            <span className="text-slate-700 dark:text-slate-300 text-xs font-medium">{a}</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>

        <div className="mt-4 mb-8 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-5 rounded-2xl shadow-lg">
           <div className="flex justify-between items-center">
               <div>
                   <p className="text-slate-500 dark:text-slate-400 text-xs mb-1">Fee per hour</p>
                   <h2 className="text-2xl font-bold text-slate-900 dark:text-white uppercase tracking-tighter">
                       <span className="text-xs font-bold text-brand-secondary mr-1">UGX</span>
                       {turf.pricePerHour.toLocaleString()}
                   </h2>
               </div>
               <button onClick={() => setStep('booking')} className="bg-brand-secondary text-white dark:text-black px-8 py-4 rounded-xl font-black uppercase tracking-widest shadow-lg active:scale-95 transition-transform">
                   Book Slot
               </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import { Layout } from '../components/Layout';
import { TURFS } from '../constants';
import { useNavigate } from 'react-router-dom';
import { MapPin, Navigation, Star, ChevronLeft, Search, Calendar } from 'lucide-react';

// Custom Marker Icon to match theme
const createCustomIcon = (color: string) => {
    return L.divIcon({
        html: `<div style="background-color: ${color}; width: 32px; height: 32px; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); display: flex; align-items: center; justify-content: center; border: 2px solid white; box-shadow: 0 4px 6px rgba(0,0,0,0.3);">
                <div style="transform: rotate(45deg); width: 10px; height: 10px; background-color: white; border-radius: 50%;"></div>
               </div>`,
        className: 'custom-div-icon',
        iconSize: [32, 32],
        iconAnchor: [16, 32],
        popupAnchor: [0, -32]
    });
};

const emeraldIcon = createCustomIcon('#10b981');

// Component to handle map movements
const FlyToLocation = ({ coords }: { coords: [number, number] }) => {
    const map = useMap();
    useEffect(() => {
        if (coords) map.flyTo(coords, 14);
    }, [coords, map]);
    return null;
};

export const ExploreMap: React.FC = () => {
    const navigate = useNavigate();
    const [selectedTurf, setSelectedTurf] = useState(TURFS[0]);
    const [searchTerm, setSearchTerm] = useState('');

    const filteredTurfs = TURFS.filter(t => 
        t.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.location.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const handleBookNow = (e: React.MouseEvent, turfId: string) => {
        e.stopPropagation();
        navigate(`/turf/${turfId}`, { state: { initialStep: 'booking' } });
    };

    return (
        <Layout>
            <div className="h-[calc(100vh-80px)] flex flex-col relative animate-fadeIn">
                {/* Overlay UI: Top Bar */}
                <div className="absolute top-4 left-4 right-4 z-[1000] flex gap-3">
                    <button 
                        onClick={() => navigate(-1)}
                        className="bg-white dark:bg-slate-900 p-3 rounded-2xl shadow-xl text-slate-900 dark:text-white border border-slate-200 dark:border-slate-800"
                    >
                        <ChevronLeft size={24} />
                    </button>
                    <div className="flex-1 bg-white dark:bg-slate-900 rounded-2xl shadow-xl flex items-center px-4 border border-slate-200 dark:border-slate-800">
                        <Search className="text-slate-400" size={18} />
                        <input 
                            type="text" 
                            placeholder="Find a pitch..."
                            className="bg-transparent border-none outline-none text-slate-900 dark:text-white ml-3 w-full text-sm font-bold uppercase tracking-tight"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                </div>

                {/* Map Implementation */}
                <div className="flex-1 bg-slate-900">
                    <MapContainer 
                        center={[0.33, 32.60]} 
                        zoom={13} 
                        style={{ height: '100%', width: '100%' }}
                        zoomControl={false}
                    >
                        <TileLayer
                            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
                            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
                        />
                        {filteredTurfs.map(turf => (
                            <Marker 
                                key={turf.id} 
                                position={turf.coordinates || [0,0]} 
                                icon={emeraldIcon}
                                eventHandlers={{
                                    click: () => setSelectedTurf(turf)
                                }}
                            >
                                <Popup className="custom-popup">
                                    <div className="p-1 min-w-[150px]">
                                        <h4 className="font-bold text-slate-900 mb-1">{turf.name}</h4>
                                        <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mb-3">UGX {turf.pricePerHour.toLocaleString()}/hr</p>
                                        <div className="flex gap-2">
                                            <button 
                                                onClick={() => navigate(`/turf/${turf.id}`)}
                                                className="flex-1 bg-slate-100 text-slate-600 py-2 rounded-lg text-[10px] font-bold uppercase tracking-wide hover:bg-slate-200 transition-colors"
                                            >
                                                Details
                                            </button>
                                            <button 
                                                onClick={(e) => handleBookNow(e, turf.id)}
                                                className="flex-1 bg-brand-secondary text-white py-2 rounded-lg text-[10px] font-bold uppercase tracking-wide hover:opacity-90 transition-opacity"
                                            >
                                                Book
                                            </button>
                                        </div>
                                    </div>
                                </Popup>
                            </Marker>
                        ))}
                        <FlyToLocation coords={selectedTurf.coordinates || [0,0]} />
                    </MapContainer>
                </div>

                {/* Bottom Card for Selected Turf */}
                <div className="absolute bottom-6 left-4 right-4 z-[1000] animate-slideUp">
                    <div className="bg-white dark:bg-slate-900 p-5 rounded-[2.5rem] shadow-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-between">
                        <div className="flex items-center space-x-4">
                            <div className="w-16 h-16 rounded-2xl overflow-hidden shadow-inner bg-slate-100 dark:bg-slate-800">
                                <img src={selectedTurf.image} className="w-full h-full object-cover" />
                            </div>
                            <div>
                                <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter leading-none">{selectedTurf.name}</h3>
                                <p className="text-[10px] text-slate-500 font-bold uppercase flex items-center mt-2">
                                    <MapPin size={10} className="mr-1 text-brand-secondary" /> {selectedTurf.location.split(',')[0]}
                                </p>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <button 
                                onClick={() => navigate(`/turf/${selectedTurf.id}`)}
                                className="w-14 h-14 bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all"
                            >
                                <ArrowRight size={24} />
                            </button>
                            <button 
                                onClick={(e) => handleBookNow(e, selectedTurf.id)}
                                className="w-14 h-14 bg-brand-secondary text-white dark:text-black rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all"
                                title="Book Now"
                            >
                                <Calendar size={24} />
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </Layout>
    );
};

const ArrowRight = ({ size }: { size: number }) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14m-7-7 7 7-7 7"/></svg>
);
